script.lang:
DO $patch$
DECLARE
    level1_id bigint;
    level2_id bigint;
    report_feature bigint;
BEGIN
    SELECT id, parent INTO STRICT level1_id, report_feature
    FROM amp_fields_visibility
    WHERE name = 'Indicator Disaggregation Level 1'
      AND parent IN (SELECT id FROM amp_features_visibility WHERE name = 'Reports');

    SELECT id INTO level2_id FROM amp_fields_visibility
    WHERE name = 'Indicator Disaggregation Level 2' AND parent = report_feature;
    IF level2_id IS NULL THEN
        INSERT INTO amp_fields_visibility (id, name, description, haslevel, parent)
        VALUES (nextval('amp_fields_visibility_seq'), 'Indicator Disaggregation Level 2',
                'Indicator Disaggregation Level 2', false, report_feature)
        RETURNING id INTO level2_id;
        INSERT INTO amp_fields_templates (template, field)
        SELECT template, level2_id FROM amp_fields_templates WHERE field = level1_id;
    END IF;
END
$patch$@
